-- =====================================================================
--  CARDÁPIO Pizzaria Tu·Bab's (transcrito do cardápio impresso)
--  Rode DEPOIS do schema.sql. ATENÇÃO: apaga o cardápio e as bordas atuais
--  e coloca este no lugar (os pedidos antigos NÃO são afetados).
--  Broto: calculada automaticamente (50% da grande; +R$ 5 no meio a meio).
-- =====================================================================
update public.settings set store_name = 'Pizzaria Tu·Bab''s', store_address = 'R. Vitor Monaldo, 141 - Jd Master, Araçoiaba da Serra - SP, 18190-000', delivery_fee = 6, delivery_per_km = 1.50, delivery_condo_fee = 12, broto_percent = 50, broto_half_extra = 5 where id = 1;
truncate table public.products, public.borders restart identity;
-- Bebidas entram DESLIGADAS com preço de exemplo: confira o preço no painel e ligue.

-- Bordas recheadas (tabela da loja). Borda vulcão: só na pizza grande.
